package com.mdmuntakim.mobhead;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * Maps an entity key to a skin texture value. The file is generated by
 * {@code tools/generate-head-catalog.py}; values are portable base64 texture
 * properties understood by the vanilla client.
 */
public final class HeadCatalog {

    public record Texture(String value, String name, String category) {
    }

    private final Map<String, Texture> textures;

    private HeadCatalog(Map<String, Texture> textures) {
        this.textures = Collections.unmodifiableMap(textures);
    }

    public static HeadCatalog empty() {
        return new HeadCatalog(Map.of());
    }

    public static HeadCatalog load(JavaPlugin plugin) {
        try (InputStream stream = plugin.getResource("mobheads.tsv")) {
            if (stream == null) {
                plugin.getLogger().warning("mobheads.tsv is not packaged in the jar; no custom textures available.");
                return empty();
            }
            try (Reader reader = new InputStreamReader(stream, StandardCharsets.UTF_8)) {
                return parse(new BufferedReader(reader));
            }
        } catch (IOException exception) {
            plugin.getLogger().warning("Could not read mobheads.tsv: " + exception.getMessage());
            return empty();
        }
    }

    static HeadCatalog parse(BufferedReader reader) throws IOException {
        Map<String, Texture> result = new LinkedHashMap<>();
        String line;
        while ((line = reader.readLine()) != null) {
            if (line.isBlank() || line.startsWith("#")) {
                continue;
            }
            String[] parts = line.split("\t", -1);
            if (parts.length < 2 || parts[0].isBlank() || parts[1].isBlank()) {
                continue;
            }
            String key = parts[0].trim().toLowerCase(java.util.Locale.ROOT);
            String name = parts.length > 2 ? parts[2] : key;
            String category = parts.length > 3 ? parts[3] : "";
            result.put(key, new Texture(parts[1].trim(), name, category));
        }
        return new HeadCatalog(result);
    }

    public Texture get(String entityKey) {
        return textures.get(entityKey.toLowerCase(java.util.Locale.ROOT));
    }

    public int size() {
        return textures.size();
    }

    public Map<String, Texture> textures() {
        return textures;
    }
}
